"""Scam scenarios, part 5: situations found missing by a corpus test (tests/scam_corpus.py) and further situations that lead to scams. See scam_scen_core.py.
Each entry gives the specific explanation and specific steps for that situation. fr/rw/sw wording is a DRAFT for fluent review."""
from scam_scen_core import add, widen

_SEND = r"(?:send|sends|transfer|pay|deposit|wire|envoy|vers|virez|payez|reglez|ohereza|nyohereza|mwohereze|kohereza|ishyura|wishyure|banza wishyure|tuma|nitumie|tumeni|lipa|toa)\w*"
_ASKRET = r"(?:return|refund|give back|send (?:it )?back|renvoy|rends|rendez|rembours|subiza|subize|nsubize|ansubize|uyansubize|rudisha|nirudishie|nirudishe|garuza|reverse)\w*"
_AMT = r"(?:\d[\d.,  ]{2,}\s?(?:k|m|rwf|frw|usd|eur|kes|ugx|tzs|ksh|\$|dollars?|euros?)?|\d[\d., ]*\s?(?:million|millions|miliyoni|milioni))"

# 1 --------------------------------------------------------------------------------------------------------------- advance-fee "trustee" / inheritance
add("advance_fee_trustee", "high", ["r:(?:\\b\\d[\\d.,]*\\s?(?:million|millions|miliyoni|milioni|milliard|billion)|\\b(?:million|millions|miliyoni|milioni)\\s+(?:za\\s+)?(?:\\d|dollars?|dolari|dola|usd|euros?)|\\b\\d{1,3}(?:,\\d{3}){2,}\\b)",
        "r:\\b(?:trusted|trustworthy|reliable|honest|de confiance|wizewe|kuaminika|next of kin|beneficiar\\w*|foreign partner|help me (?:to )?(?:receive|transfer|claim|invest|move)|died without|unclaimed|umurage|urithi|heritage|inheritance|trunk|consignment|dormant account|\\bwill\\b)\\w*"],
    ("Advance-fee 'millions waiting for you' trap (trustee / next of kin / hidden fortune)", "Piège des « millions qui vous attendent » (homme de confiance / héritier / fortune cachée)", "Uburiganya bwa «miliyoni zigutegereje» (umuntu wizewe / umuragwa / umutungo wihishe)", "Mtego wa «mamilioni yanakusubiri» (mtu wa kuaminika / mrithi / mali iliyofichwa)"),
    ("A stranger offers you a share of a huge sum (soldier's box, dead client's account, lawyer's inheritance, businessman's transfer). The money does not exist. After you reply you will be asked for 'fees', 'taxes', 'a lawyer', 'clearance' again and again, and for your ID and bank details.",
     "Un inconnu vous offre une part d'une somme énorme (caisse d'un soldat, compte d'un client décédé, héritage, transfert d'un homme d'affaires). L'argent n'existe pas. Après votre réponse, on vous demandera sans cesse des « frais », « taxes », « avocat », « dédouanement », ainsi que vos pièces d'identité et coordonnées bancaires.",
     "Umuntu utazi aragusezeranya igice cy'amafaranga menshi cyane (isanduku y'umusirikare, konti y'uwapfuye, umurage, ihererekanya ry'umucuruzi). Ayo mafaranga ntabaho. Nusubiza uzasabwa «amafaranga y'ibyangombwa», «imisoro», «avoka», «kurekura» ubudahwema, n'indangamuntu na konti yawe ya banki.",
     "Mgeni anakupa sehemu ya kiasi kikubwa sana (sanduku la askari, akaunti ya marehemu, urithi, uhamisho wa mfanyabiashara). Pesa hizo hazipo. Ukijibu utaombwa «ada», «kodi», «wakili», «kibali» mara kwa mara, pamoja na kitambulisho na taarifa za benki."),
    ("Do not reply, do not send your ID, passport, selfie or bank details, and never pay any 'fee' to receive money. | Nobody you have never met gives away millions: delete the message and block the sender. | If you already sent documents, tell your bank, watch your accounts, and be careful of anyone who later calls claiming to 'help recover' your money (that is a second scam). | Report to the police (RIB in Rwanda) or the cybercrime unit and to your telecom operator.",
     "Ne répondez pas, n'envoyez ni pièce d'identité, passeport, selfie ni coordonnées bancaires, et ne payez jamais de « frais » pour recevoir de l'argent. | Personne que vous n'avez jamais rencontré ne donne des millions : supprimez le message et bloquez l'expéditeur. | Si vous avez déjà envoyé des documents, prévenez votre banque, surveillez vos comptes et méfiez-vous de ceux qui proposent ensuite de « récupérer » votre argent (seconde arnaque). | Signalez à la police (RIB au Rwanda) ou à l'unité de cybercriminalité et à votre opérateur.",
     "Ntusubize, ntohereze indangamuntu, pasiporo, selfie cyangwa amakuru ya banki, kandi ntukishyure «amafaranga» ngo wakire amafaranga. | Nta muntu utigeze ubona uguha miliyoni: siba ubutumwa uhagarike uwabwohereje. | Niba waramaze kohereza ibyangombwa, menyesha banki yawe, ukurikirane konti, kandi witondere abakuvugisha nyuma bakubwira ko bagufasha «kugarura» amafaranga (ni uburiganya bwa kabiri). | Bimenyeshe polisi (RIB mu Rwanda) cyangwa ishami rishinzwe ibyaha byo kuri interineti na sosiyete ya telefone.",
     "Usijibu, usitume kitambulisho, pasipoti, selfie au taarifa za benki, na kamwe usilipe «ada» ili kupokea pesa. | Hakuna mtu usiyemjua anayegawa mamilioni: futa ujumbe na umzuie. | Ikiwa tayari ulituma nyaraka, mjulishe benki yako, fuatilia akaunti, na jihadhari na watakaokupigia baadaye wakisema watakusaidia «kurejesha» pesa (utapeli wa pili). | Ripoti polisi au kitengo cha uhalifu wa mtandao na kampuni yako ya simu."), strong=True)

# 2 --------------------------------------------------------------------------------------------------------------- call-forwarding USSD
add("ussd_call_forward", "high", ["r:(?:^|[\\s(\"'])\\*{1,2}(?:21|61|62|67|004|401|57|21)\\*\\+?\\d{6,}"],
    ("Call-forwarding USSD code (steals your calls and verification codes)", "Code USSD de renvoi d'appel (vole vos appels et codes de vérification)", "Kode ya USSD yohereza ahandi telefoni (yiba amahamagara na kode zawe)", "Msimbo wa USSD wa kupeleka simu (huiba simu na misimbo yako)"),
    ("Codes that start with *21*, *61*, *62*, *67*, *004* or **21* followed by a number forward your calls (and the SMS/voice codes sent to you) to the scammer's number. With them they can take over your WhatsApp, MoMo and bank accounts.",
     "Les codes commençant par *21*, *61*, *62*, *67*, *004* ou **21* suivis d'un numéro renvoient vos appels (et les codes SMS/vocaux) vers le numéro de l'escroc. Avec cela ils prennent le contrôle de votre WhatsApp, MoMo et comptes bancaires.",
     "Kode zitangira kuri *21*, *61*, *62*, *67*, *004* cyangwa **21* zikurikirwa na nimero zohereza amahamagara yawe (na kode za SMS/ijwi) kuri nimero y'umutekamutwe. Bamufasha gufata WhatsApp, MoMo na konti zawe za banki.",
     "Misimbo inayoanza na *21*, *61*, *62*, *67*, *004* au **21* ikifuatiwa na namba hupeleka simu zako (na misimbo ya SMS/sauti) kwa namba ya tapeli. Kwa hiyo wanachukua WhatsApp, M-Pesa/MoMo na akaunti zako za benki."),
    ("Do NOT dial it. Delete the message. | If you already dialled it, dial ##002# (or the code your operator gives) now to cancel all forwarding, and check your settings. | Change the PIN of your mobile money and secure your WhatsApp with two-step verification. | Tell your operator and your contacts that your number may be misused.",
     "Ne le composez PAS. Supprimez le message. | Si vous l'avez composé, composez tout de suite ##002# (ou le code de votre opérateur) pour annuler tous les renvois, et vérifiez vos réglages. | Changez le PIN de votre argent mobile et activez la validation en deux étapes de WhatsApp. | Prévenez votre opérateur et vos contacts que votre numéro peut être utilisé à mauvais escient.",
     "NTUGIKORESHE. Siba ubutumwa. | Niba waramaze kugikoresha, kanda ##002# (cyangwa kode ya sosiyete yawe) ako kanya kugira ngo uhagarike ukohereza kose, urebe n'iboneza ryawe. | Hindura PIN ya mobile money ushyireho ibyiciro bibiri bya WhatsApp. | Menyesha sosiyete yawe n'inshuti zawe ko nimero yawe ishobora gukoreshwa nabi.",
     "USIPIGE. Futa ujumbe. | Ikiwa umeshapiga, piga ##002# (au msimbo wa kampuni yako) sasa kufuta upelekaji wote, na kagua mipangilio. | Badilisha PIN ya pesa za simu na washa uthibitisho wa hatua mbili kwenye WhatsApp. | Mjulishe mtoa huduma na marafiki zako kuwa namba yako inaweza kutumiwa vibaya."), strong=True)

# 3 --------------------------------------------------------------------------------------------------------------- USSD prize / bundle
add("ussd_prize_code", "medium", ["r:(?:^|[\\s(\"'])\\*\\d{2,4}\\*[\\d*#]*#?", "r:\\b(?:free|gift|bundle|bonus|activate|activ\\w+|claim|win|won|prize|confirm|delivery|gratuit|cadeau|forfait|ku buntu|igihembo|kora|zawadi|bure|kifurushi|thibitisha)\\w*"],
    ("Dial-this-code trick (free bundle, gift or 'confirm delivery')", "Astuce du « composez ce code » (forfait gratuit, cadeau, « confirmer la livraison »)", "Uburiganya bwa «kanda iyi kode» (data y'ubuntu, impano, «emeza ko wakiriye»)", "Hila ya «piga msimbo huu» (kifurushi bure, zawadi, «thibitisha uwasilishaji»)"),
    ("Scammers send USSD codes that look like promotions. Some move your airtime or mobile money, change your PIN or forward your calls. A real operator promotion does not need you to dial a code you received from an unknown message.",
     "Les escrocs envoient des codes USSD qui ressemblent à des promotions. Certains transfèrent votre crédit ou argent mobile, changent votre PIN ou renvoient vos appels. Une vraie promotion d'opérateur ne demande pas de composer un code reçu d'un message inconnu.",
     "Abatekamutwe bohereza kode za USSD zisa n'ibishya bya sosiyete. Zimwe zimurura amafaranga cyangwa airtime, zihindura PIN cyangwa zohereza amahamagara ahandi. Promosiyo nyayo ntisaba gukanda kode wabonye mu butumwa butazwi.",
     "Matapeli hutuma misimbo ya USSD inayoonekana kama ofa. Mingine huhamisha salio au pesa za simu, hubadilisha PIN au hupeleka simu. Ofa halisi ya kampuni haihitaji kupiga msimbo uliopokea kutoka kwa ujumbe usiojulikana."),
    ("Do not dial the code. Ask your operator's official app or customer care (from a number you looked up yourself) whether the offer exists. | If you dialled it, check your balance, change your mobile-money PIN and tell the operator. | Delete the message and block the number.",
     "Ne composez pas le code. Vérifiez l'offre dans l'appli officielle de l'opérateur ou auprès du service client (numéro trouvé par vous). | Si vous l'avez composé, vérifiez votre solde, changez le PIN et prévenez l'opérateur. | Supprimez le message et bloquez le numéro.",
     "Ntukande kode. Baza sosiyete yawe muri porogaramu yayo yemewe cyangwa kuri serivisi y'abakiriya (nimero wishakiye) niba iyo promosiyo ibaho. | Niba warayikanze, reba amafaranga yawe, uhindure PIN ubimenyeshe sosiyete. | Siba ubutumwa uhagarike iyo nimero.",
     "Usipige msimbo. Uliza kampuni kupitia programu rasmi au huduma kwa wateja (namba uliyoitafuta mwenyewe) kama ofa ipo. | Ikiwa umepiga, kagua salio, badilisha PIN na mjulishe mtoa huduma. | Futa ujumbe na mzuie namba."))

# 4 --------------------------------------------------------------------------------------------------------------- new number family money
add("new_number_family_money", "high", ["r:\\b(?:new number|changed (?:my )?(?:phone )?number|lost (?:my )?phone|broke (?:my )?phone|broken (?:my )?phone|phone (?:is )?(?:broken|damaged|stolen|lost)|j'ai change de numero|nouveau numero|telephone (?:est )?(?:casse|perdu|vole)|nahinduye nimero|nimero nshya|telefoni yanjye (?:yavunitse|yatakaye|yarabuze|yibwe)|nimebadilisha namba|namba mpya|simu yangu (?:imeharibika|imepotea|imeibiwa)|nimepoteza simu)",
        "r:(?:\\b(?:mum|mom|mama|maman|dad|papa|mummy|daddy|son|daughter|auntie|uncle|it's me|c'est moi|ni njye|ni mimi|mubyeyi|mzazi)\\b|" + _SEND + ")", "r:" + _SEND],
    ("'It's me, new number' family money request", "« C'est moi, nouveau numéro » : demande d'argent à la famille", "«Ni njye, nimero nshya»: gusaba amafaranga umuryango", "«Ni mimi, namba mpya»: ombi la pesa kwa familia"),
    ("A scammer pretends to be your child, parent or relative on a new number and asks for money 'urgently' because the phone broke or a bill is due. They hope you will not call the old number to check.",
     "Un escroc se fait passer pour votre enfant, parent ou proche sur un nouveau numéro et demande de l'argent « d'urgence » parce que le téléphone est cassé ou qu'une facture est due. Il espère que vous n'appellerez pas l'ancien numéro.",
     "Umutekamutwe yiyoberanya nk'umwana wawe, umubyeyi cyangwa umuvandimwe kuri nimero nshya akagusaba amafaranga «byihutirwa» kuko telefoni yapfuye cyangwa hari umwenda. Yizera ko utazahamagara nimero ya kera ngo ugenzure.",
     "Tapeli hujifanya mtoto wako, mzazi au ndugu kwa namba mpya na kuomba pesa «haraka» kwa sababu simu imeharibika au kuna deni. Anatumaini hutapiga namba ya zamani kuthibitisha."),
    ("Call the person's OLD number, or another relative who knows them, before sending anything. | Ask a question only the real person can answer (a family nickname, the last time you met); scammers cannot. | Ask for a voice or video call; if they refuse or make excuses, stop. | Never send money to a new number because of a text. Save nothing under that name until confirmed. | Block and report the number.",
     "Appelez l'ANCIEN numéro de la personne, ou un autre proche, avant d'envoyer quoi que ce soit. | Posez une question dont seule la vraie personne connaît la réponse (surnom familial, dernière rencontre). | Demandez un appel vocal ou vidéo ; s'il refuse ou invente des excuses, arrêtez. | N'envoyez jamais d'argent à un nouveau numéro à cause d'un SMS. N'enregistrez pas ce nom avant confirmation. | Bloquez et signalez le numéro.",
     "Hamagara nimero ya KERA y'uwo muntu, cyangwa undi muvandimwe umuzi, mbere yo kohereza ikintu. | Baza ikibazo gusa uwo muntu nyawe ashobora gusubiza (akabyiniriro, igihe mwaherukanye). | Saba guhamagara kw'ijwi cyangwa video; nangira urwitwazo, hagarara. | Ntukohereze amafaranga kuri nimero nshya kubera SMS. Ntubike izina ryayo utarabyemeza. | Hagarika kandi umenyeshe iyo nimero.",
     "Piga namba ya ZAMANI ya mtu huyo, au ndugu mwingine anayemjua, kabla ya kutuma chochote. | Uliza swali ambalo mtu halisi pekee anaweza kujibu (jina la utani, mara ya mwisho mlipokutana). | Omba simu ya sauti au video; akikataa au kutoa visingizio, simama. | Usitume pesa kwa namba mpya kwa sababu ya SMS. Usihifadhi jina hilo hadi uthibitishe. | Mzuie na uripoti namba."), strong=True)

# 5 --------------------------------------------------------------------------------------------------------------- fixed returns in a short time
add("returns_fixed_time", "high", ["r:\\b(?:invest\\w*|shor\\w+|wekez\\w+|put in|deposit|stake|place|investi\\w*|mettez|versez)\\b", "r:\\b(?:receive|get|earn|make|withdraw|recevez|gagnez|obtenez|ubone|upate|uhabwe|utahabwa|upokee|utapata|pata|rudi)\\w*\\s+\\d[\\d.,  ]*",
        "r:(?:\\b(?:after|within|in|dans|en|mu|ndani ya|baada ya|ndani)\\s+(?:\\d+|a|an|one|une|un|1)\\s*(?:day|days|hour|hours|week|weeks|month|jour|jours|heures?|semaines?|mois|iminsi|umunsi|icyumweru|amasaha|siku|wiki|saa|mwezi)|\\bmu\\s+minsi\\s+\\d+|\\bndani ya\\s+siku\\s+\\d+)"],
    ("Fixed fast returns: 'invest X, receive 3X in days' (Ponzi / fake investment)", "Rendements fixes rapides : « investissez X, recevez 3X en quelques jours » (Ponzi / faux investissement)", "Inyungu zihamye vuba: «shora X ubone 3X mu minsi» (Ponzi / ishoramari ry'impimbano)", "Faida isiyobadilika kwa haraka: «wekeza X upate 3X ndani ya siku» (Ponzi / uwekezaji bandia)"),
    ("No real investment multiplies your money several times in days. Early 'winners' are paid with the money of new victims and shown as screenshots; when enough people have paid, the scheme disappears or says 'pay a tax/fee to withdraw'.",
     "Aucun vrai investissement ne multiplie votre argent en quelques jours. Les premiers « gagnants » sont payés avec l'argent des nouvelles victimes et montrés en captures d'écran ; quand assez de gens ont payé, le système disparaît ou exige « une taxe pour retirer ».",
     "Nta ishoramari nyaryo rikuba amafaranga yawe inshuro nyinshi mu minsi. Abatsinze ba mbere bishyurwa amafaranga y'abahohotewe bashya bakerekanwa mu mashusho; abantu bamaze kuba benshi, gahunda irazimira cyangwa igasaba «umusoro wo kubikuza».",
     "Hakuna uwekezaji halisi unaozidisha pesa mara kadhaa ndani ya siku. «Washindi» wa mwanzo hulipwa kwa pesa za waathirika wapya na kuonyeshwa kwa picha; wakijaza wengi, mpango hupotea au kudai «kodi ya kutoa»."),
    ("Do not send money. Ask who is licensed to take deposits: in Rwanda check with the National Bank of Rwanda (BNR) or the Capital Market Authority (CMA); elsewhere your regulator. | Treat screenshots and testimonials as worthless: they are easy to fake. | If you already paid, stop paying, do not 'recruit' friends, keep proofs, and report to the police and your operator or bank. | Never pay a 'tax' or 'fee' to withdraw your profits.",
     "N'envoyez pas d'argent. Vérifiez qui est autorisé à recevoir des dépôts : au Rwanda la Banque nationale (BNR) ou l'autorité des marchés de capitaux (CMA) ; ailleurs votre régulateur. | Les captures et témoignages ne valent rien : ils se falsifient facilement. | Si vous avez payé, ne payez plus, ne « recrutez » personne, gardez les preuves et signalez à la police et à votre opérateur ou banque. | Ne payez jamais de « taxe » ou « frais » pour retirer vos gains.",
     "Ntohereze amafaranga. Baza uwemerewe kwakira amafaranga: mu Rwanda reba Banki Nkuru (BNR) cyangwa CMA; ahandi reba urwego rubishinzwe. | Amashusho n'ubuhamya nta gaciro bifite: biroroshye guhimbwa. | Niba waramaze kwishyura, hagarika kwishyura, ntuzane inshuti, bika ibimenyetso, umenyeshe polisi na sosiyete cyangwa banki. | Ntukishyure «umusoro» cyangwa «amafaranga» yo kubikuza inyungu.",
     "Usitume pesa. Uliza nani ana leseni ya kupokea amana: Rwanda angalia BNR au CMA; kwingineko mdhibiti wako. | Picha za skrini na ushuhuda havina thamani: ni rahisi kughushi. | Ikiwa umeshalipa, acha kulipa, usiwaalike marafiki, hifadhi ushahidi, na ripoti polisi na kampuni ya simu au benki. | Kamwe usilipe «kodi» au «ada» ya kutoa faida."), strong=True)

# 6 --------------------------------------------------------------------------------------------------------------- betting tips
add("betting_tips_fee", "high", ["r:\\b(?:bet|bets|betting|fixed match|fixed matches|sure win|sure odds|sure tips|jackpot|odds|tips|paris sportif\\w*|match truque|pronostic\\w*|kubeti|gutega|ubutega|kuweka dau|mechi iliyopangwa|ushindi wa uhakika|dau)\\b",
        "r:" + _SEND + "|\\b(?:vip|join|rejoin\\w*|jiunge|injira|subscription|abonnement|membership|unlock|access)\\w*"],
    ("Paid 'fixed match' betting tips", "« Matchs truqués » et pronostics payants", "«Imikino yateguwe» n'inama zo kubeti zishyurwa", "Vidokezo vya kubeti vya «mechi zilizopangwa» vya kulipia"),
    ("Nobody can fix matches and sell the result for a small fee: if they could they would bet themselves. Sellers of 'sure tips' simply collect fees from many people and disappear, or ask for more after a 'lost' tip.",
     "Personne ne peut truquer des matchs et vendre le résultat pour quelques frais : il parierait lui-même. Les vendeurs de « tuyaux sûrs » collectent des frais auprès de nombreux gens puis disparaissent ou en réclament plus après un « perdu ».",
     "Nta wapanga imikino ngo ayigurishe ku mafaranga make: yabeti ubwe. Abagurisha «inama zizewe» bakusanya amafaranga y'abantu benshi bagacika, cyangwa bagasaba andi nyuma yo «gutsindwa».",
     "Hakuna anayepanga mechi na kuuza matokeo kwa ada ndogo: angeweka dau mwenyewe. Wauzaji wa «vidokezo vya uhakika» hukusanya ada kutoka kwa wengi kisha hupotea au kuomba zaidi baada ya «kupoteza»."),
    ("Do not pay for tips or to 'join a VIP group'. | Bet only with licensed operators, only money you can afford to lose, and set a limit. | If you already paid, stop and do not chase losses; block the seller and report to the platform.",
     "Ne payez pas pour des tuyaux ou pour « rejoindre un groupe VIP ». | Pariez seulement chez des opérateurs agréés, avec un argent que vous pouvez perdre, et fixez une limite. | Si vous avez payé, arrêtez et ne cherchez pas à vous refaire ; bloquez le vendeur et signalez à la plateforme.",
     "Ntukishyure inama cyangwa «kwinjira mu itsinda rya VIP». | Tega gusa ku bafite uruhushya, n'amafaranga ushobora gutakaza, ushyireho umupaka. | Niba warishyuye, hagarara ntugerageze kwiyishyura; hagarika umugurisha ubimenyeshe urubuga.",
     "Usilipe vidokezo wala «kujiunga na kundi la VIP». | Weka dau kwa waendeshaji wenye leseni tu, kwa pesa unazoweza kupoteza, na weka kikomo. | Ukishalipa, acha na usijaribu kurudisha hasara; mzuie muuzaji na uripoti kwenye jukwaa."))

# 7 --------------------------------------------------------------------------------------------------------------- medical fundraising from unknown
add("medical_fundraising_unknown", "medium", ["r:\\b(?:sick|ill|surgery|operation|cancer|hospital|medical|treatment|bills?|dialysis|malade|chirurgie|hopital|soins|kuvurwa|indwara|ibitaro|uburwayi|mgonjwa|upasuaji|hospitali|matibabu)\\w*", "r:\\b(?:help|please help|any amount|donate|donation|support|aide|don|inkunga|nsabye|nsaba|ndagusaba|saidia|changia|msaada|naomba)\\w*", "r:(?:this number|iyi nimero|namba hii|ce numero|\\+?\\d{9,}|0\\d{9})"],
    ("Medical / emergency fundraising from someone you cannot verify", "Collecte pour soins ou urgence par quelqu'un que vous ne pouvez pas vérifier", "Gukusanya inkunga y'ubuvuzi cyangwa ibyihutirwa ku muntu udashobora kugenzura", "Kuchangisha kwa matibabu au dharura kutoka kwa mtu usiyeweza kuthibitisha"),
    ("Fake appeals use real-sounding illnesses, children and hospitals to move you to send money to a personal number. Genuine appeals can be checked with the hospital, the family or a known organisation.",
     "Les faux appels utilisent des maladies, enfants et hôpitaux crédibles pour vous faire envoyer de l'argent à un numéro personnel. Les vrais appels se vérifient auprès de l'hôpital, de la famille ou d'une organisation connue.",
     "Ubutumwa bw'impimbano bukoresha indwara, abana n'ibitaro bisa n'ukuri kugira ngo wohereze amafaranga kuri nimero bwite. Ubutumwa nyabwo bushobora kugenzurwa ku bitaro, mu muryango cyangwa mu muryango uzwi.",
     "Maombi bandia hutumia magonjwa, watoto na hospitali zinazoaminika ili utume pesa kwa namba binafsi. Maombi halisi yanathibitishwa hospitalini, kwa familia au shirika linalojulikana."),
    ("Ask for the hospital's name and call its official number to confirm the patient and the bill. | Prefer paying the hospital directly or a registered organisation, not a personal number. | If the sender is a stranger or a 'friend' you cannot reach by phone, do not send money. | Beware of photos: they are often copied from other people.",
     "Demandez le nom de l'hôpital et appelez son numéro officiel pour confirmer le patient et la facture. | Préférez payer l'hôpital directement ou une organisation enregistrée, pas un numéro personnel. | Si l'expéditeur est un inconnu ou un « ami » injoignable, n'envoyez rien. | Méfiez-vous des photos : souvent copiées sur d'autres personnes.",
     "Saba izina ry'ibitaro uhamagare nimero yabyo yemewe wemeze umurwayi n'inyemezabwishyu. | Hitamo kwishyura ibitaro ubwabyo cyangwa umuryango wanditswe, si nimero bwite. | Niba ubwohereje ari umuntu utazi cyangwa «inshuti» utavugana nayo kuri telefone, ntuzohereze. | Wirinde amafoto: akenshi yakopowe ku bandi.",
     "Uliza jina la hospitali na upige namba yake rasmi kuthibitisha mgonjwa na bili. | Pendelea kulipa hospitali moja kwa moja au shirika lililosajiliwa, si namba binafsi. | Mtumaji akiwa mgeni au «rafiki» usiyeweza kumpata kwa simu, usitume. | Jihadhari na picha: mara nyingi zimenakiliwa kutoka kwa wengine."))

# 8 --------------------------------------------------------------------------------------------------------------- stranded traveller
add("stranded_friend_money", "high", ["r:\\b(?:stuck|stranded|robbed|mugged|stolen|lost my (?:wallet|bag|passport|phone)|bloque|vole|agress|nibwe|nacikiwe|nibwe|nimeibiwa|nimekwama|nimeporwa|amekwama)\\w*", "r:" + _SEND, "r:\\b(?:friend|number|account|ticket|hotel|airport|embassy|ami|numero|compte|billet|inshuti|nimero|konti|itike|rafiki|namba|tiketi|uwanja wa ndege|aeroport)\\w*"],
    ("'I am stranded / robbed abroad, send money' (hacked-friend or fake traveller)", "« Je suis bloqué / dévalisé à l'étranger, envoyez de l'argent » (ami piraté ou faux voyageur)", "«Nabuze inzira / nibwe hanze, ohereza amafaranga» (inshuti yibwe konti cyangwa umugenzi w'impimbano)", "«Nimekwama / nimeibiwa nje ya nchi, tuma pesa» (rafiki aliyedukuliwa au msafiri bandia)"),
    ("A scammer, often using a hacked account of someone you know, claims to be stuck, robbed or in hospital and asks for urgent money to a third-party number so you cannot trace it.",
     "Un escroc, souvent avec le compte piraté d'une connaissance, prétend être bloqué, dévalisé ou à l'hôpital et réclame de l'argent en urgence vers un numéro tiers pour brouiller les pistes.",
     "Umutekamutwe, akenshi akoresheje konti yibwe y'umuntu uzi, avuga ko yagumye mu nzira, yibwe cyangwa ari mu bitaro agasaba amafaranga byihutirwa kuri nimero y'undi kugira ngo atamenyekana.",
     "Tapeli, mara nyingi kwa akaunti iliyodukuliwa ya mtu unayemjua, hudai amekwama, ameibiwa au yuko hospitali na kuomba pesa haraka kwa namba ya mtu wa tatu ili asigundulike."),
    ("Call the person on a number you already have; do not use the number in the message. | Call their family or a mutual friend to check where they really are. | Never send money to a third-party number for someone you have not heard speak. | If their account was hacked, tell them through another channel so they can recover it.",
     "Appelez la personne sur un numéro que vous avez déjà ; n'utilisez pas celui du message. | Appelez sa famille ou un ami commun pour vérifier où elle est vraiment. | N'envoyez jamais d'argent à un numéro tiers pour quelqu'un que vous n'avez pas entendu parler. | Si son compte est piraté, prévenez-la par un autre canal pour qu'elle le récupère.",
     "Hamagara uwo muntu kuri nimero usanganywe; ntukoreshe iri mu butumwa. | Hamagara umuryango we cyangwa inshuti mufitanye isano ugenzure aho ari. | Ntukohereze amafaranga ku wundi muntu kuri nimero y'undi udafite ibimenyetso ko uwo muntu avugana nawe. | Niba konti ye yibwe, mubwire unyuze ahandi kugira ngo ayigarure.",
     "Mpigie mtu huyo kwa namba uliyo nayo; usitumie ile ya ujumbe. | Piga familia yake au rafiki wa pamoja kuhakiki alipo kweli. | Kamwe usitume pesa kwa namba ya mtu wa tatu kwa mtu ambaye hujamsikia akiongea. | Ikiwa akaunti yake imedukuliwa, mjulishe kwa njia nyingine aifufue."), strong=True)

# 9 --------------------------------------------------------------------------------------------------------------- bank login request
add("bank_login_request", "high", ["r:\\b(?:bank|banking|internet banking|online banking|mobile banking|banque|banki|bk|equity|ecobank|cogebanque|i&m|access)\\b", "r:\\b(?:login|log in|log-in|username|user name|password|credentials|identifiants|mot de passe|mdp|konti ya banki|ijambo ry'ibanga|jina la mtumiaji|nenosiri)\\w*", "r:(?:\\b(?:need|require|send me|give me|share|provide|complete|finish|process|besoin|donnez|envoyez|nkeneye|mpa|mumpe|nipe|nahitaji|nipatie)\\b)"],
    ("Request for your online-banking login 'to complete a payment'", "Demande de vos identifiants bancaires « pour finaliser un paiement »", "Gusaba amakuru yo kwinjira muri banki «kugira ngo arangize kwishyura»", "Ombi la taarifa za kuingia benki «kukamilisha malipo»"),
    ("No genuine payer, buyer, employer or 'business partner' needs your online-banking login to send you money; money is received with only your account number. Giving login details lets them empty your account.",
     "Aucun vrai payeur, acheteur, employeur ou « partenaire » n'a besoin de vos identifiants bancaires pour vous envoyer de l'argent ; il suffit de votre numéro de compte. Les donner leur permet de vider votre compte.",
     "Nta wishyura, umuguzi, umukoresha cyangwa «umufatanyabikorwa» nyawe ukeneye amakuru yawe yo kwinjira muri banki kugira ngo akohereze amafaranga; hakenerwa nimero ya konti gusa. Kuyatanga bibemerera gusiba konti yawe.",
     "Hakuna mlipaji, mnunuzi, mwajiri au «mshirika wa biashara» halisi anayehitaji taarifa zako za kuingia benki kutuma pesa; nambari ya akaunti inatosha. Kuzitoa kunawaruhusu kuimaliza akaunti yako."),
    ("Never share your online-banking username, password, PIN or OTP with anyone. | Give only your account number (and name) for receiving money. | If you already shared, change your password at once from the official app, call your bank's official number and freeze the account. | Report the sender to the bank and police.",
     "Ne communiquez jamais identifiant, mot de passe, PIN ou OTP bancaires. | Donnez seulement votre numéro de compte (et nom) pour recevoir de l'argent. | Si vous les avez donnés, changez le mot de passe aussitôt depuis l'appli officielle, appelez le numéro officiel de la banque et bloquez le compte. | Signalez l'expéditeur à la banque et à la police.",
     "Ntuzigere utanga izina, ijambo ry'ibanga, PIN cyangwa OTP bya banki ku muntu uwo ari we wese. | Tanga nimero ya konti n'izina gusa kugira ngo wakire amafaranga. | Niba warabitanze, hindura ijambo ry'ibanga ako kanya muri porogaramu yemewe, uhamagare banki kuri nimero yemewe ufunge konti. | Bimenyeshe banki na polisi.",
     "Kamwe usishiriki jina, nenosiri, PIN au OTP ya benki. | Toa nambari ya akaunti (na jina) tu kupokea pesa. | Ikiwa umeshatoa, badilisha nenosiri mara moja kupitia programu rasmi, piga namba rasmi ya benki na ugandishe akaunti. | Ripoti mtumaji benki na polisi."), strong=True)

# 10 -------------------------------------------------------------------------------------------------------------- crypto pump / managed
add("crypto_pump_manage", "high", ["CRYPTO", "r:\\b(?:triple|double|10x|100x|moon|mooning|explode|skyrocket|will (?:rise|go up)|going to (?:rise|explode)|before (?:it'?s|it is) too late|pre-?sale|insider|manage your (?:account|funds|portfolio)|i can manage|trade for you|send (?:usdt|btc|bitcoin|eth)|wallet address|percent of (?:the )?profits?|\\d+ ?% of (?:the )?profits?|share of (?:the )?profits?|gucunga konti|kusimamia akaunti)\\w*"],
    ("Crypto 'price will explode' / 'I will manage your account' scheme", "Combine crypto « le prix va exploser » / « je gère votre compte »", "Uburiganya bwa crypto «igiciro kigiye kuzamuka» / «ndagucungira konti»", "Mpango wa crypto «bei itapanda» / «nitakusimamia akaunti»"),
    ("Pump-and-dump groups and 'managed accounts' push you to buy a coin or send crypto to a wallet the scammer controls. Crypto transfers cannot be reversed and the 'profits' on the screen are fake.",
     "Les groupes « pump and dump » et « comptes gérés » vous poussent à acheter une pièce ou à envoyer des crypto vers un portefeuille contrôlé par l'escroc. Les transferts crypto sont irréversibles et les « profits » à l'écran sont faux.",
     "Amatsinda ya «pump and dump» na «konti zicungwa» agusunikira kugura crypto cyangwa kohereza crypto kuri wallet y'umutekamutwe. Ihererekanya rya crypto ntirisubizwa kandi «inyungu» zigaragara ni ibinyoma.",
     "Vikundi vya «pump and dump» na «akaunti zinazosimamiwa» hukusukuma kununua sarafu au kutuma crypto kwenye pochi anayoidhibiti tapeli. Uhamisho wa crypto hauwezi kurudishwa na «faida» kwenye skrini ni bandia."),
    ("Never send crypto to a wallet because someone asked, and never give anyone your seed phrase or exchange login. | Nobody can promise a price: ignore 'tips' from strangers. | Use only regulated exchanges and test with tiny amounts. | If you sent funds, report the wallet address to the exchange and the police; recovery 'agents' who contact you later are also scammers.",
     "N'envoyez jamais de crypto vers un portefeuille parce qu'on vous le demande, et ne donnez jamais votre phrase de récupération ni vos identifiants. | Personne ne peut promettre un prix : ignorez les « tuyaux » d'inconnus. | N'utilisez que des plateformes réglementées et testez avec de petites sommes. | Si vous avez envoyé des fonds, signalez l'adresse à la plateforme et à la police ; les « agents de récupération » qui vous contactent sont aussi des escrocs.",
     "Ntukohereze crypto kuri wallet kubera ko babikubwiye, kandi ntutange seed phrase cyangwa amakuru yawe yo kwinjira. | Nta wamenya igiciro: ntukizere «inama» z'abantu utazi. | Koresha gusa ibigo bigenzurwa ugerageze n'amafaranga make. | Niba warohereje, bimenyeshe urubuga na polisi; «abafasha kugarura» baguhamagara nabo ni abatekamutwe.",
     "Kamwe usitume crypto kwenye pochi kwa sababu umeombwa, na usimpe mtu seed phrase au taarifa za kuingia. | Hakuna anayeweza kuahidi bei: puuza «vidokezo» vya wageni. | Tumia mabadilishano yenye udhibiti na jaribu kwa kiasi kidogo. | Ukituma, ripoti anwani ya pochi kwenye jukwaa na polisi; «mawakala wa kurejesha» wanaokutafuta pia ni matapeli."), strong=True)

# 11 -------------------------------------------------------------------------------------------------------------- friendly stranger opener
add("friendly_stranger_opener", "medium", ["r:^\\W*(?:hi|hello|hey|good (?:morning|afternoon|evening)|bonjour|salut|bonsoir|muraho|mwaramutse|mwiriwe|amakuru|habari|jambo|mambo|vipi)\\b", "r:\\b(?:i saw your (?:photo|profile|picture|number|post)|found your (?:number|profile|contact)|got your (?:number|contact)|your (?:photo|profile) (?:is |looks )?(?:nice|beautiful|lovely|handsome)|where are you from|do we know each other|do you remember me|long time|we met|friends|make friends|be friends|nice to meet|wrong number|j'ai vu ta photo|j'ai trouve ton numero|on se connait|tu me reconnais|on peut etre amis|nabonye ifoto yawe|nabonye nimero yawe|turaziranye|waba wibuka|ni nde|nimeona picha yako|nimepata namba yako|tunafahamiana|kuwa marafiki|namba isiyo sahihi)"],
    ("Friendly message from a stranger (how many scams start)", "Message amical d'un inconnu (comment commencent beaucoup d'arnaques)", "Ubutumwa bw'urugwiro bw'utazi (uko uburiganya bwinshi butangira)", "Ujumbe wa kirafiki kutoka kwa mgeni (jinsi utapeli mwingi unavyoanza)"),
    ("Romance, investment and job scams often begin with a harmless 'hi, I saw your photo' or 'wrong number' message. The aim is to start a chat, build trust, then ask for money, a code or a move to another app.",
     "Les arnaques sentimentales, d'investissement ou d'emploi commencent souvent par un « bonjour, j'ai vu ta photo » ou « faux numéro » anodin. Le but est de lancer la discussion, gagner la confiance puis demander de l'argent, un code ou de passer sur une autre appli.",
     "Uburiganya bw'urukundo, ishoramari n'akazi bukunze gutangira n'ubutumwa busa n'ubutagira icyo butwaye nka «muraho, nabonye ifoto yawe» cyangwa «nimero itari yo». Intego ni ugutangiza ikiganiro, kubona icyizere, hanyuma gusaba amafaranga, kode cyangwa kwimukira kuri indi porogaramu.",
     "Utapeli wa mapenzi, uwekezaji na ajira mara nyingi huanza na ujumbe usio na madhara kama «hujambo, nimeona picha yako» au «namba isiyo sahihi». Lengo ni kuanzisha mazungumzo, kujenga uaminifu, kisha kuomba pesa, msimbo au kuhamia programu nyingine."),
    ("You do not have to reply. If you do, share nothing personal and no photos of documents. | Search their photo (reverse image search) and look for inconsistent stories; do not trust profile pictures. | Be alert if they quickly move to WhatsApp/Telegram, talk about money, investments or gifts, or avoid a video call. | Never send money, codes or passwords to someone you have not met in person. | Block and report if it escalates.",
     "Vous n'êtes pas obligé de répondre. Si vous répondez, ne partagez rien de personnel ni photo de documents. | Faites une recherche inversée de sa photo et cherchez des histoires incohérentes ; ne vous fiez pas aux photos de profil. | Méfiez-vous s'il passe vite sur WhatsApp/Telegram, parle d'argent, d'investissements ou de cadeaux, ou évite l'appel vidéo. | N'envoyez jamais d'argent, codes ou mots de passe à quelqu'un que vous n'avez pas rencontré. | Bloquez et signalez si cela s'intensifie.",
     "Ntugomba gusubiza. Niba usubije, ntugire icyo utanga cy'ibanga cyangwa amafoto y'ibyangombwa. | Shakisha ifoto ye ku mbuga (reverse image search) urebe inkuru zivuguruzanya; ntukizere amafoto y'umwirondoro. | Witondere nihihuta kujya kuri WhatsApp/Telegram, avuga amafaranga, ishoramari cyangwa impano, cyangwa yanga guhamagara kuri video. | Ntuzigere wohereza amafaranga, kode cyangwa amagambo y'ibanga ku muntu mutarahura. | Hagarika kandi umenyeshe niba bikomeje.",
     "Huna wajibu wa kujibu. Ukijibu, usishiriki chochote binafsi wala picha za nyaraka. | Tafuta picha yake (reverse image search) na uangalie hadithi zisizoendana; usiamini picha za wasifu. | Tahadhari akihamia haraka WhatsApp/Telegram, akizungumzia pesa, uwekezaji au zawadi, au akikwepa simu ya video. | Kamwe usitume pesa, misimbo au nywila kwa mtu ambaye hujakutana naye. | Mzuie na uripoti kama inaongezeka."))

# 12 -------------------------------------------------------------------------------------------------------------- who viewed your profile
add("profile_viewers_link", "high", ["r:\\b(?:who (?:viewed|visited|checked|looked at|stalk\\w*)|see who|profile viewers?|viewed your (?:profile|status)|qui a (?:vu|visite)|voir qui|abakurebye|uwabonye|aliyetazama|aliyeangalia)\\w*", "LINK"],
    ("'See who viewed your profile' link", "Lien « voir qui a consulté votre profil »", "Link ya «reba abakurebye»", "Kiungo cha «ona aliyetazama wasifu wako»"),
    ("No app can show who viewed your WhatsApp, Facebook or Instagram profile. These links steal your login or install spyware.",
     "Aucune appli ne peut montrer qui a consulté votre profil WhatsApp, Facebook ou Instagram. Ces liens volent vos identifiants ou installent un logiciel espion.",
     "Nta porogaramu ishobora kwerekana abareba umwirondoro wawe wa WhatsApp, Facebook cyangwa Instagram. Izi link ziba amakuru yawe yo kwinjira cyangwa zishyiraho porogaramu y'ubutasi.",
     "Hakuna programu inayoweza kuonyesha nani ametazama wasifu wako wa WhatsApp, Facebook au Instagram. Viungo hivi huiba taarifa zako za kuingia au kusakinisha programu ya upelelezi."),
    ("Do not open the link or enter any login. | If you did, change your password right away, turn on two-step verification and log out of all devices. | Do not forward it: this is how it spreads.",
     "N'ouvrez pas le lien et ne saisissez aucun identifiant. | Si vous l'avez fait, changez tout de suite le mot de passe, activez la validation en deux étapes et déconnectez tous les appareils. | Ne le transférez pas : c'est ainsi qu'il se propage.",
     "Ntufungure link kandi ntushyiremo ijambo ry'ibanga. | Niba warabikoze, hindura ijambo ry'ibanga ako kanya, ushyireho ibyiciro bibiri, usohoke ku bikoresho byose. | Ntukayiyohereze: ni uko ikwirakwira.",
     "Usifungue kiungo wala kuweka nenosiri. | Ikiwa umefanya hivyo, badilisha nenosiri mara moja, washa uthibitisho wa hatua mbili na utoke kwenye vifaa vyote. | Usiisambaze: ndivyo inavyoenea."), strong=True)

# 13 -------------------------------------------------------------------------------------------------------------- card / billing update
add("billing_update_phish", "high", ["r:\\b(?:update|mettez a jour|mettre a jour|confirm\\w*|verify|renew|vugurura|emeza|sasisha|thibitisha|hakiki)\\w*\\W+(?:\\w+\\W+){0,6}(?:card|carte|payment|billing|bank details|coordonnees bancaires|ikarita|kadi|malipo|uburyo bwo kwishyura|payment method|moyen de paiement)", "r:\\b(?:suspend\\w*|blocked|failed|declined|expired|expire\\w*|unpaid|overdue|echou\\w*|refuse|impaye|inaniwe|yanze|imeshindwa|imekataliwa|imesimamishwa|yahagaritswe|fungwa|itafungwa|unpaid)\\w*"],
    ("'Your subscription payment failed, update your card' phishing", "Hameçonnage « paiement échoué, mettez à jour votre carte »", "Phishing ya «kwishyura byanze, vugurura ikarita yawe»", "Hadaa ya «malipo yameshindwa, sasisha kadi yako»"),
    ("Fake billing notices copy Netflix, Canal+, DStv, Spotify, Apple or your telecom. The link opens a copy of the real page that records your card number, expiry date and the 3 digits (CVV), then the code you get by SMS.",
     "De faux avis de facturation imitent Netflix, Canal+, DStv, Spotify, Apple ou votre opérateur. Le lien ouvre une copie de la vraie page qui enregistre numéro de carte, date d'expiration et les 3 chiffres (CVV), puis le code reçu par SMS.",
     "Ubutumwa bw'impimbano bwo kwishyura bwigana Netflix, Canal+, DStv, Spotify, Apple cyangwa sosiyete yawe. Link ifungura kopi y'urupapuro nyarwo ifata nimero y'ikarita, itariki irangiriraho n'imibare 3 (CVV), hanyuma kode ubonye kuri SMS.",
     "Taarifa bandia za malipo huiga Netflix, Canal+, DStv, Spotify, Apple au kampuni yako ya simu. Kiungo hufungua nakala ya ukurasa halisi inayorekodi nambari ya kadi, tarehe ya kuisha na tarakimu 3 (CVV), kisha msimbo unaopata kwa SMS."),
    ("Do not click. Open the service's official app or type its address yourself to see if there is a real billing problem. | Never type card number, CVV or SMS codes on a page you reached from a message. | If you did, call your bank at once to block the card, and check recent charges. | Report the message as phishing to the real company.",
     "Ne cliquez pas. Ouvrez l'appli officielle du service ou tapez vous-même l'adresse pour voir s'il y a un vrai problème de facturation. | Ne saisissez jamais numéro de carte, CVV ou codes SMS sur une page atteinte depuis un message. | Si vous l'avez fait, appelez immédiatement votre banque pour bloquer la carte et vérifiez les débits. | Signalez le message comme hameçonnage à la vraie entreprise.",
     "Ntukande. Fungura porogaramu yemewe cyangwa wandike aderesi ubwawe urebe niba hari ikibazo nyacyo. | Ntuzigere ushyira nimero y'ikarita, CVV cyangwa kode ya SMS ku rupapuro rwavuye mu butumwa. | Niba warabikoze, hamagara banki ako kanya ufunge ikarita ureba n'amafaranga yakuwe. | Menyesha ikigo nyacyo ko ari phishing.",
     "Usibofye. Fungua programu rasmi ya huduma au andika anwani mwenyewe uone kama kuna tatizo halisi la malipo. | Kamwe usiweke nambari ya kadi, CVV au misimbo ya SMS kwenye ukurasa uliofika kutoka ujumbe. | Ikiwa umefanya, piga benki mara moja kufunga kadi na kagua makato. | Ripoti ujumbe kama hadaa kwa kampuni halisi."), strong=True)

# 14 -------------------------------------------------------------------------------------------------------------- mistaken transfer (wide)
add("mistaken_transfer_wide", "high", ["r:\\b(?:by mistake|mistakenly|accidentally|wrong (?:number|account)|par erreur|erreur|par inadvertance|kubw'impanuka|kimakosa|nabibeshye|nimekosea|nibeshye|kwibeshya)\\w*", "r:" + _ASKRET, "r:(?:" + _AMT + "|\\b(?:money|mobile money|momo|compte|account|konti|akaunti|amafaranga|pesa|argent)\\b)"],
    ("'I sent money to you by mistake, please return it' (wide match)", "« J'ai envoyé de l'argent par erreur, merci de le renvoyer »", "«Nohereje amafaranga kubw'impanuka, ndakwinginze uyansubize»", "«Nimekutumia pesa kimakosa, tafadhali nirudishie»"),
    ("The 'transfer' SMS is fake or the real transfer will be reversed. If you send money back you lose your own money.",
     "Le SMS de « transfert » est faux ou le vrai transfert sera annulé. Si vous renvoyez de l'argent, vous perdez le vôtre.",
     "SMS y'«ihererekanya» ni iy'impimbano cyangwa ihererekanya nyaryo rizakurwaho. Nusubiza amafaranga uzaba utakaje ayawe.",
     "SMS ya «uhamisho» ni bandia au uhamisho halisi utarudishwa. Ukirudisha pesa, unapoteza zako."),
    ("Check your balance in your own app or by the official USSD code before anything else. | If real money arrived, tell the sender to ask their operator or bank to reverse it; do not send it yourself. | Do not give your PIN. | Block and report the number.",
     "Vérifiez d'abord votre solde dans votre appli ou avec le code USSD officiel. | Si de l'argent est vraiment arrivé, l'expéditeur doit demander l'annulation à son opérateur ou sa banque ; ne le renvoyez pas vous-même. | Ne donnez pas votre PIN. | Bloquez et signalez le numéro.",
     "Banza urebe amafaranga yawe muri porogaramu yawe cyangwa kode ya USSD yemewe. | Niba amafaranga yageze koko, uwayohereje abwire sosiyete cyangwa banki ayasubize; ntukayasubize ubwawe. | Ntutange PIN. | Hagarika kandi umenyeshe nimero.",
     "Kagua salio kwanza kwenye programu yako au kwa msimbo rasmi wa USSD. | Pesa zikifika kweli, mtumaji aombe kampuni au benki kuzirejesha; usizirudishe mwenyewe. | Usitoe PIN. | Mzuie na uripoti namba."), strong=True)

# 15 -------------------------------------------------------------------------------------------------------------- loan with upfront insurance/fee (wide)
add("loan_upfront_wide", "high", ["LOAN", "r:\\b(?:no collateral|without collateral|no guarantor|no credit check|sans garantie|sans caution|nta ngwate|bila dhamana|bila mdhamini|instant|approved|pre-?approved|within \\d+ ?(?:minutes?|mins?|hours?)|in \\d+ ?(?:minutes?|mins?)|10 minutes|kwemerwa|imeidhinishwa|approuve)\\w*", "r:\\b(?:insurance|assurance|fee|fees|frais|deposit|processing|registration|ubwishingizi|bima|ada|ikiguzi|amafaranga y\\w+|avance|pay first|payer d'abord|banza wishyure|lipa kwanza|lipa bima)\\w*"],
    ("Loan that needs 'insurance' or a fee first", "Prêt qui exige d'abord une « assurance » ou des frais", "Inguzanyo isaba mbere «ubwishingizi» cyangwa amafaranga", "Mkopo unaohitaji «bima» au ada kwanza"),
    ("A real lender deducts fees from the loan or after approval inside its official app; it does not ask you to send 'insurance' to a personal number first. The loan never arrives and more 'fees' follow.",
     "Un vrai prêteur déduit ses frais du prêt ou après approbation dans son appli officielle ; il ne demande pas d'envoyer une « assurance » à un numéro personnel. Le prêt n'arrive jamais et d'autres « frais » suivent.",
     "Ugurizanya nyawe akata amafaranga ku nguzanyo cyangwa nyuma yo kwemererwa muri porogaramu yemewe; ntasaba kohereza «ubwishingizi» kuri nimero bwite. Inguzanyo ntiza kandi hakabaho andi «mafaranga».",
     "Mkopeshaji halisi hukata ada kutoka kwenye mkopo au baada ya idhini ndani ya programu rasmi; haombi kutuma «bima» kwa namba binafsi. Mkopo haufiki na «ada» zaidi hufuata."),
    ("Do not pay anything before you receive a loan. | Check the lender is licensed (in Rwanda the National Bank of Rwanda publishes licensed institutions). | Use only your bank, SACCO or an app you can verify. | If you paid, stop, keep the proof and report to the police and your operator.",
     "Ne payez rien avant de recevoir un prêt. | Vérifiez que le prêteur est agréé (au Rwanda la Banque nationale publie la liste). | N'utilisez que votre banque, SACCO ou une appli vérifiable. | Si vous avez payé, arrêtez, gardez la preuve et signalez à la police et à votre opérateur.",
     "Ntukishyure ikintu mbere yo kubona inguzanyo. | Reba ko uguriza afite uruhushya (mu Rwanda Banki Nkuru isohora urutonde). | Koresha banki yawe, SACCO cyangwa porogaramu ushobora kugenzura. | Niba warishyuye, hagarara, bika ibimenyetso ubimenyeshe polisi na sosiyete.",
     "Usilipe chochote kabla ya kupokea mkopo. | Hakiki mkopeshaji ana leseni (Rwanda Benki Kuu huchapisha orodha). | Tumia benki yako, SACCO au programu unayoweza kuithibitisha. | Ukishalipa, acha, hifadhi ushahidi na uripoti polisi na kampuni ya simu."), strong=True)

# 16 -------------------------------------------------------------------------------------------------------------- rent / property prepayment
add("rent_prepay_keys_sent", "high", ["HOUSE", "r:" + _SEND + "|\\b(?:deposit|advance|reserve|reservation|avance|reserver|mbere|hifadhi|first month|mois d'avance|ukwezi kwa mbere|mwezi wa kwanza|kodi ya mwezi)\\w*", "r:\\b(?:keys?|cles?|imfunguzo|funguo|courier|owner (?:is )?abroad|abroad|a l'etranger|iburaya|nje ya nchi|sent by|will be sent|seront envoyees|turazohereza|zitatumwa|kutumwa|cannot meet|can't meet|not (?:in|around)|ntabwo ndi)\\w*"],
    ("Rental / property: pay first, keys sent later (owner 'abroad')", "Location / immobilier : payez d'abord, clés envoyées plus tard (propriétaire « à l'étranger »)", "Ubukode / inzu: banza wishyure, imfunguzo zizoherezwa (nyir'inzu «hanze»)", "Kupangisha / mali: lipa kwanza, funguo zitatumwa (mmiliki «nje ya nchi»)"),
    ("The 'owner' copies photos of a real house, is always abroad or busy, and asks for rent or a deposit to 'reserve' it before you can visit. Once you pay, the number goes silent.",
     "Le « propriétaire » copie des photos d'une vraie maison, est toujours à l'étranger ou occupé, et demande loyer ou caution pour « réserver » avant visite. Après paiement, le numéro ne répond plus.",
     "«Nyir'inzu» yiba amafoto y'inzu nyayo, aba ari hanze cyangwa afite akazi, agasaba ubukode cyangwa ingwate yo «kubika» mbere yo gusura. Umaze kwishyura, nimero ntisubiza.",
     "«Mmiliki» hunakili picha za nyumba halisi, yuko nje ya nchi au ana shughuli, na kuomba kodi au amana ya «kuhifadhi» kabla ya kuitazama. Ukilipa, namba hainyanyui."),
    ("Visit the house in person and meet the real owner or agent before paying anything. | Check who really owns it (neighbours, sector/cell office, a registered agent). | Pay only against a signed contract and a receipt, preferably to an account in the owner's name, never to a stranger's mobile number. | Report copied listings to the platform.",
     "Visitez la maison en personne et rencontrez le vrai propriétaire ou agent avant de payer. | Vérifiez qui est vraiment propriétaire (voisins, secteur/cellule, agent enregistré). | Ne payez que contre un contrat signé et un reçu, de préférence sur un compte au nom du propriétaire, jamais sur le mobile d'un inconnu. | Signalez les annonces copiées à la plateforme.",
     "Sura inzu ku giti cyawe uhure na nyir'inzu cyangwa umuhuza nyawe mbere yo kwishyura. | Genzura nyir'inzu nyawe (abaturanyi, ibiro by'umurenge/akagari, umuhuza wanditswe). | Ishyura gusa ufite amasezerano asinywe n'inyemezabwishyu, ku konti y'izina rya nyir'inzu, atari nimero y'umuntu utazi. | Menyesha urubuga ibyatangajwe byakopowe.",
     "Tembelea nyumba mwenyewe na ukutane na mmiliki au wakala halisi kabla ya kulipa. | Hakiki mmiliki halisi (majirani, ofisi ya kata/mtaa, wakala aliyesajiliwa). | Lipa kwa mkataba uliosainiwa na risiti pekee, ikiwezekana kwa akaunti ya jina la mmiliki, si namba ya mgeni. | Ripoti matangazo yaliyonakiliwa kwa jukwaa."), strong=True)

# 17 -------------------------------------------------------------------------------------------------------------- faith seed (wide)
add("faith_seed_wide", "high", ["r:\\b(?:pastor|pasteur|pasiteri|mchungaji|prophet|prophete|umuhanuzi|nabii|man of god|apostle|apotre|umwungeri|bishop|evang\\w*)\\w*", "r:\\b(?:seed|semence|imbuto|mbegu|offering|sow|sowing|plant|gutera|panda|kupanda|point|vow)\\w*", "r:\\b(?:multipl\\w*|tenfold|blessing|miracle|breakthrough|kubura|kukubira|kuzidishia|inshuro|mara kumi|dix fois|benediction|ubwiyongere)\\w*"],
    ("'Plant a seed and God will multiply it' payment request", "Demande de paiement « semez une graine et Dieu la multipliera »", "Gusaba amafaranga «tera imbuto Imana izakubira»", "Ombi la malipo «panda mbegu na Mungu atazidisha»"),
    ("Some fake 'men of God' and impersonators of known pastors ask for 'seeds' by MoMo with promises of tenfold return, healing or breakthrough. Giving is a personal, voluntary matter; promises of guaranteed return in exchange for money are a hallmark of fraud.",
     "Certains faux « hommes de Dieu » et imitateurs de pasteurs connus demandent des « semences » par MoMo avec promesse de gains décuplés, guérison ou percée. Donner est un acte libre ; promettre un retour garanti contre de l'argent est une marque de fraude.",
     "Abahimbano «abakozi b'Imana» n'abiyoberanya abapasitori bazwi basaba «imbuto» kuri MoMo bavuga ko izikuba inshuro icumi, gukira cyangwa gutera imbere. Gutanga ni ugushaka k'umuntu; kwizeza inyungu zemewe kugira ngo yishyure ni ikimenyetso cy'uburiganya.",
     "Baadhi ya «watu wa Mungu» bandia na wanaoiga wachungaji maarufu huomba «mbegu» kwa MoMo wakiahidi mara kumi, uponyaji au mafanikio. Kutoa ni hiari; ahadi ya faida ya uhakika kwa pesa ni alama ya ulaghai."),
    ("Check with your own church leaders in person; official collections go through your congregation's known channels. | Do not send money to personal numbers claiming to be a minister. | Give only what you freely choose and can afford, never under pressure or for a promise.",
     "Vérifiez auprès des responsables de votre église en personne ; les collectes officielles passent par les canaux connus de votre communauté. | N'envoyez pas d'argent à des numéros personnels se disant ministres. | Donnez seulement ce que vous choisissez librement et pouvez vous permettre, jamais sous pression ni pour une promesse.",
     "Reba abayobozi b'itorero ryawe imbonankubone; amaturo nyakuri anyura mu miyoboro izwi y'itorero. | Ntukohereze amafaranga ku nimero bwite zivuga ko ari iz'umupasitori. | Tanga gusa ibyo wihitiyemo ushoboye, ntiwigere ubikora ku gahato cyangwa kubera isezerano.",
     "Thibitisha kwa viongozi wa kanisa lako ana kwa ana; sadaka rasmi hupitia njia zinazojulikana za kanisa. | Usitume pesa kwa namba binafsi zinazodai kuwa za mchungaji. | Toa unachochagua kwa hiari na unachoweza, kamwe si kwa shinikizo au ahadi."))

# 18 -------------------------------------------------------------------------------------------------------------- parcel fee (no link needed)
add("parcel_fee_pay", "high", ["PARCEL", "r:\\b(?:pay|payez|reglez|reglement|ishyura|ishyurwa|wishyure|lipa|ada|gharama|fee|fees|frais|tax|clearance|dedouan\\w*|release|libere\\w*|redelivery|customs|douane|forodha)\\w*", "r:(?:" + _AMT + ")"],
    ("Parcel held at customs / redelivery fee", "Colis retenu à la douane / frais de relivraison", "Ipaki ifungiye kuri douane / amafaranga yo kongera kuyigeza", "Kifurushi kimeshikiliwa forodha / ada ya kuletwa tena"),
    ("Scammers send fake courier or customs messages with a small fee, so you pay and type your card details on a fake page. Real couriers do not take fees through a link in an SMS.",
     "Les escrocs envoient de faux messages de transporteur ou de douane avec de petits frais pour que vous payiez et saisissiez votre carte sur une fausse page. Les vrais transporteurs ne prennent pas de frais via un lien reçu par SMS.",
     "Abatekamutwe bohereza ubutumwa bw'impimbano bw'abatwara ibicuruzwa cyangwa douane basaba amafaranga make kugira ngo wishyure ushyire n'ikarita ku rupapuro rw'impimbano. Abatwara nyabo ntibaca amafaranga kuri link yo muri SMS.",
     "Matapeli hutuma ujumbe bandia wa msafirishaji au forodha wenye ada ndogo ili ulipe na kuweka kadi kwenye ukurasa bandia. Wasafirishaji halisi hawakusanyi ada kupitia kiungo cha SMS."),
    ("Are you expecting a parcel? If not, ignore it. If yes, check the tracking number on the courier's own app or website (typed by you). | Do not pay or type card details through the message. | If you paid, call your bank to block the card, then report the sender.",
     "Attendez-vous un colis ? Sinon, ignorez. Si oui, vérifiez le numéro de suivi sur l'appli ou le site du transporteur (saisi par vous). | Ne payez pas et ne saisissez pas votre carte via le message. | Si vous avez payé, appelez votre banque pour bloquer la carte puis signalez l'expéditeur.",
     "Ese utegereje ipaki? Niba atari byo, ntukabyiteho. Niba ari byo, reba nimero yo gukurikirana kuri porogaramu cyangwa urubuga rw'umutwara (wiyandikiye). | Ntukishyure cyangwa ngo ushyire ikarita ku butumwa. | Niba warishyuye, hamagara banki ufunge ikarita ubone kumenyesha uwoherejwe.",
     "Je, unatarajia kifurushi? Kama sivyo, puuza. Kama ndiyo, hakiki nambari ya ufuatiliaji kwenye programu au tovuti ya msafirishaji (uliyoandika mwenyewe). | Usilipe wala kuweka kadi kupitia ujumbe. | Ukishalipa, piga benki kufunga kadi kisha uripoti mtumaji."))

# 19 -------------------------------------------------------------------------------------------------------------- grandparent / relative in trouble with police
add("relative_trouble_secret", "high", ["r:\\b(?:mubyeyi|umubyeyi|mzazi|wazazi|grand(?:son|daughter|child|ma|pa)|nephew|niece|petit-?fils|petite-?fille|neveu|niece|umwuzukuru|mjukuu|mpwa|umuhungu wawe|mwanao|son|daughter|your child|ton fils|ta fille|mwana wawe|mtoto wako)\\b|\\b(?:it's me|c'est moi|ni njye|ni mimi)\\b", "r:\\b(?:police|polisi|arrest\\w*|accident|trouble|jail|prison|lawyer|bail|hospital|kaga|matatani|ajali|gereza|hospitali|garde a vue|avocat|kaution|dalili|amefungwa)\\w*", "r:\\b(?:do not tell|don't tell|dont tell|keep (?:it )?secret|ne dis rien|ne le dis pas|ntubibwire|ntukabwire|usiwaambie|usimwambie|siri|ibanga|secret)\\w*"],
    ("'I'm in trouble, don't tell my parents, send money' (family emergency scam, may use a cloned voice)", "« Je suis dans le pétrin, ne dis rien à mes parents, envoie de l'argent » (arnaque à l'urgence familiale, voix possiblement clonée)", "«Ndi mu kaga, ntubwire ababyeyi, ohereza amafaranga» (uburiganya bw'ibyihutirwa mu muryango, ijwi rishobora gukopwa)", "«Niko matatani, usiwaambie wazazi, tuma pesa» (utapeli wa dharura ya familia, sauti inaweza kunakiliwa)"),
    ("The scammer plays a child or grandchild in trouble, begs for secrecy and wants money at once. The secrecy is to stop you from checking with the family. A voice call can also be an AI-cloned voice.",
     "L'escroc joue un enfant ou petit-enfant en difficulté, implore le secret et veut de l'argent tout de suite. Le secret empêche de vérifier avec la famille. Un appel vocal peut aussi être une voix clonée par IA.",
     "Umutekamutwe yiyoberanya umwana cyangwa umwuzukuru uri mu kaga, agasaba ibanga akarenzaho kwihutisha amafaranga. Ibanga rigamije kukubuza kugenzura mu muryango. Guhamagara kw'ijwi gushobora kuba ijwi ryakopowe na AI.",
     "Tapeli hujifanya mtoto au mjukuu aliye matatani, huomba siri na kutaka pesa mara moja. Siri ni ya kukuzuia kuhakiki na familia. Simu ya sauti pia inaweza kuwa sauti iliyonakiliwa na AI."),
    ("Hang up and call the person directly on the number you already know, and a parent or relative. | Agree a family code word in advance for emergencies. | Never send money, even 'just a little', because of a secret request. | Real police and courts never ask for bail by mobile money to a personal number.",
     "Raccrochez et appelez directement la personne sur le numéro que vous connaissez, et un parent. | Convenez à l'avance d'un mot de code familial pour les urgences. | N'envoyez jamais d'argent, même « un peu », à cause d'une demande secrète. | La vraie police et les tribunaux ne demandent jamais de caution par mobile money sur un numéro personnel.",
     "Funga telefoni uhamagare uwo muntu ku nimero uzi, n'umubyeyi cyangwa umuvandimwe. |Emeranyeho mbere ijambo ry'ibanga ry'umuryango ry'ibyihutirwa. | Ntukohereze amafaranga, ndetse n'ake, kubera icyifuzo cy'ibanga. | Polisi n'inkiko nyabyo ntibisaba ingwate kuri mobile money ku nimero bwite.",
     "Kata simu na umpigie mtu huyo moja kwa moja kwa namba unayoijua, na mzazi au ndugu. | Kubalianeni mapema neno la siri la familia kwa dharura. | Kamwe usitume pesa, hata «kidogo», kwa ombi la siri. | Polisi na mahakama halisi hawaombi dhamana kwa pesa za simu kwa namba binafsi."), strong=True)

# 20 -------------------------------------------------------------------------------------------------------------- money to a number (generic lead)
add("money_to_number", "medium", ["r:" + _SEND, "r:(?:\\b(?:to|on|at|kuri|kuri iyi|kwa|a|au|sur|vers)\\s+(?:this|iyi|hii|ce|cette|the|my|numero|nimero|namba)?\\s*(?:number|nimero|namba|numero|account|konti|compte|akaunti|momo|mobile money|wallet)\\b|\\b0?7\\d{8}\\b|\\+?250\\s?7\\d{8}|\\+?255\\s?\\d{9}|\\+?254\\s?\\d{9})", "r:(?:" + _AMT + ")"],
    ("Request to send money to a number in a message", "Demande d'envoyer de l'argent à un numéro cité dans un message", "Gusaba kohereza amafaranga kuri nimero iri mu butumwa", "Ombi la kutuma pesa kwa namba iliyo ndani ya ujumbe"),
    ("A message that names an amount and a number to pay is how most mobile-money scams end. Before sending anything you must be sure who owns the number and why you are paying.",
     "Un message qui donne un montant et un numéro à payer est l'issue de la plupart des arnaques mobile money. Avant d'envoyer, soyez sûr du propriétaire du numéro et de la raison du paiement.",
     "Ubutumwa buvuga umubare w'amafaranga na nimero yo kwishyura ni ho uburiganya bwinshi bwa mobile money burangirira. Mbere yo kohereza, uzabanze umenye nyir'iyo nimero n'impamvu wishyura.",
     "Ujumbe unaotaja kiasi na namba ya kulipa ndivyo utapeli mwingi wa pesa za simu unavyoishia. Kabla ya kutuma, hakikisha mmiliki wa namba na sababu ya kulipa."),
    ("When you type the number in your MoMo/M-Pesa app, check the name shown: it must match the person or business you mean to pay. | Confirm the request by calling the person or company on a number you already trust. | Do not pay for something you cannot see or have not agreed. | If anything is unclear, wait: a genuine request can wait an hour.",
     "Quand vous saisissez le numéro dans votre appli MoMo/M-Pesa, vérifiez le nom affiché : il doit correspondre à la personne ou l'entreprise à payer. | Confirmez la demande en appelant la personne ou l'entreprise sur un numéro de confiance. | Ne payez pas ce que vous ne voyez pas ou n'avez pas convenu. | Dans le doute, attendez : une demande légitime peut attendre une heure.",
     "Iyo wanditse nimero muri MoMo/M-Pesa, reba izina rigaragara: rigomba guhura n'umuntu cyangwa ikigo ushaka kwishyura. | Emeza icyifuzo uhamagara uwo muntu cyangwa ikigo kuri nimero wizeye. | Ntukishyure ikintu utabona cyangwa mutaremeranyaho. | Iyo hari ugushidikanya, tegereza: icyifuzo nyacyo gishobora gutegereza isaha.",
     "Ukiandika namba kwenye MoMo/M-Pesa, angalia jina linaloonekana: lazima lilingane na mtu au biashara unayokusudia kulipa. | Thibitisha ombi kwa kumpigia mtu au kampuni kwa namba unayoiamini. | Usilipe kitu usichokiona au hamjakubaliana. | Ukiwa na shaka, subiri: ombi halali linaweza kusubiri saa moja."))

# 21 -------------------------------------------------------------------------------------------------------------- pet / vehicle / ticket sale prepayment
add("pet_vehicle_ticket_prepay", "high", ["r:\\b(?:puppy|puppies|kitten|dog|cat|parrot|car|vehicle|toyota|suv|motorbike|moto|tickets?|concert|iphone|laptop|generator|chiot|chien|chat|voiture|billet|ikinyoma|imbwa|igikoko|imodoka|ikinyabiziga|itike|mbwa|gari|pikipiki|tiketi)\\w*", "r:" + _SEND + "|\\b(?:deposit|advance|shipping|delivery|courier|transport|avance|livraison|ubwikorezi|usafirishaji|kohereza)\\w*", "r:\\b(?:i am (?:travelling|abroad|overseas|in the army)|travell?ing|abroad|overseas|ship|shipped|agent|courier|send it|je voyage|a l'etranger|j'expedie|mfite urugendo|iburaya|nzayohereza|nje ya nchi|nitatuma|safarini|wakala)\\w*"],
    ("Item for sale: deposit or shipping fee first, seller 'travelling' (puppy / car / ticket / phone scam)", "Article à vendre : acompte ou frais d'expédition d'abord, vendeur « en voyage » (arnaque chiot / voiture / billet / téléphone)", "Ikintu cyo kugurisha: banza wishyure ingwate cyangwa ubwikorezi, umugurisha «ari mu rugendo»", "Bidhaa ya kuuza: lipa amana au usafirishaji kwanza, muuzaji «yuko safarini»"),
    ("Fake sellers post cheap puppies, cars, concert tickets or phones with real photos. They ask for a deposit or shipping fee, never let you see the item, and then ask for more (insurance, customs, 'vet permit').",
     "De faux vendeurs publient des chiots, voitures, billets ou téléphones bon marché avec de vraies photos. Ils demandent un acompte ou des frais d'expédition, ne laissent jamais voir l'article puis réclament encore (assurance, douane, « permis vétérinaire »).",
     "Abagurisha b'impimbano batangaza ibibwana, imodoka, amatike cyangwa telefoni bihendutse bafite amafoto nyayo. Basaba ingwate cyangwa amafaranga y'ubwikorezi, ntibakwemerera kubona icyo bagurisha, hanyuma basaba andi (ubwishingizi, douane, «uruhushya rw'inyamaswa»).",
     "Wauzaji bandia hutangaza watoto wa mbwa, magari, tiketi au simu za bei nafuu kwa picha halisi. Huomba amana au ada ya usafirishaji, hawaruhusu kuona bidhaa, kisha huomba zaidi (bima, forodha, «kibali cha mifugo»)."),
    ("See the item and meet the seller in a public place before paying; pay on handover. | A price far below market is a warning, not a bargain. | For vehicles, check the registration with the traffic authority and the seller's ID. | Do not pay deposits, 'insurance' or 'customs' to a stranger's mobile number.",
     "Voyez l'article et rencontrez le vendeur dans un lieu public avant de payer ; payez à la remise. | Un prix très inférieur au marché est un avertissement, pas une aubaine. | Pour un véhicule, vérifiez la carte grise auprès de l'autorité et la pièce du vendeur. | Ne payez pas acompte, « assurance » ou « douane » à un numéro mobile inconnu.",
     "Reba ikintu uhure n'umugurisha ahantu hahurira abantu mbere yo kwishyura; ishyura mu kugitanga. | Igiciro kiri hasi cyane y'isoko ni umuburo, si amahirwe. | Ku modoka, genzura ibyangombwa ku rwego rubishinzwe n'indangamuntu y'umugurisha. | Ntukishyure ingwate, «ubwishingizi» cyangwa «douane» kuri nimero y'umuntu utazi.",
     "Ona bidhaa na ukutane na muuzaji mahali pa umma kabla ya kulipa; lipa wakati wa kukabidhiwa. | Bei ya chini sana ya soko ni onyo, si bahati. | Kwa gari, hakiki usajili kwa mamlaka na kitambulisho cha muuzaji. | Usilipe amana, «bima» au «forodha» kwa namba ya mgeni."))

# 22 -------------------------------------------------------------------------------------------------------------- lost-and-found fee
add("lost_found_fee", "high", ["r:\\b(?:i found|we found|i have found|j'ai trouve|nous avons trouve|nabonye|twabonye|nimepata|nimekuta|tumepata)\\b", "r:\\b(?:your |ton |votre |wawe |yawe |yako |wako )?(?:phone|wallet|id(?: card)?|card|passport|bag|documents?|telephone|portefeuille|carte|passeport|sac|telefoni|ikarita|indangamuntu|pasiporo|igikapu|simu|pochi|kitambulisho|pasipoti|begi)\\b", "r:" + _SEND + "|\\b(?:reward|fee|frais|recompense|igihembo|ada|zawadi)\\w*"],
    ("'I found your phone / ID, send a fee or reward' lost-and-found scam", "« J'ai trouvé votre téléphone / pièce d'identité, envoyez des frais ou une récompense »", "«Nabonye telefoni / indangamuntu yawe, ohereza amafaranga»", "«Nimepata simu / kitambulisho chako, tuma ada au zawadi»"),
    ("Scammers 'find' items you never lost or use details from a lost item to ask for a courier fee, then keep asking.",
     "Les escrocs « trouvent » des objets que vous n'avez pas perdus ou utilisent des infos d'un objet perdu pour réclamer des frais de coursier, puis en demandent encore.",
     "Abatekamutwe «babona» ibintu utatakaje cyangwa bakoresha amakuru y'ikintu watakaje basaba amafaranga y'umutwara, hanyuma bagakomeza gusaba.",
     "Matapeli «hupata» vitu ambavyo hukupoteza au hutumia taarifa za kitu kilichopotea kudai ada ya mjumbe, kisha huendelea kuomba."),
    ("Ask them to describe something only the owner would know, and offer to meet at a police station or the local authority office. | Never pay in advance for the return of an item. | If you did lose something, report it to the police and block the SIM/cards.",
     "Demandez-leur de décrire un détail que seul le propriétaire connaît et proposez de vous retrouver au commissariat ou au bureau de l'autorité. | Ne payez jamais d'avance pour récupérer un objet. | Si vous avez vraiment perdu quelque chose, déclarez-le à la police et bloquez SIM/cartes.",
     "Basaba basobanure ikintu nyirakwo wenyine azi ubundi utange guhurira kuri sitasiyo ya polisi cyangwa ku biro by'ubuyobozi. | Ntuzigere wishyura mbere kugira ngo usubirane ikintu. | Niba waratakaje ikintu koko, kimenyeshe polisi ufunge SIM n'amakarita.",
     "Waombe waeleze kitu ambacho mmiliki pekee anakijua na upendekeze kukutana kituo cha polisi au ofisi ya mamlaka. | Kamwe usilipe mapema ili kurudishiwa kitu. | Ikiwa ulipoteza kweli, ripoti polisi na uzuie SIM/kadi."))

# 23 -------------------------------------------------------------------------------------------------------------- funeral / wedding contribution
add("contribution_unverified", "medium", ["r:\\b(?:funeral|burial|wedding|mourning|memorial|inhumation|obseques|deuil|mariage|ubukwe|gushyingura|ikiriyo|gushyingirwa|harusi|mazishi|msiba|arusi)\\w*", "r:\\b(?:contribution|contribute|donat\\w*|support|cotisation|inkunga|umusanzu|imisanzu|changia|mchango|michango|tuma|ohereza|send|envoy\\w*)\\w*", "r:(?:this number|iyi nimero|namba hii|ce numero|\\+?\\d{9,}|0\\d{9})"],
    ("Funeral / wedding contribution to a number you cannot confirm", "Cotisation pour deuil ou mariage à un numéro que vous ne pouvez pas confirmer", "Umusanzu w'ubukwe cyangwa ikiriyo kuri nimero udashobora kwemeza", "Mchango wa harusi au msiba kwa namba usiyoweza kuthibitisha"),
    ("Scammers copy real funeral and wedding committees, or invent them, and send a number for contributions. A hacked friend's account can also send the same message to everyone they know.",
     "Les escrocs copient de vrais comités de deuil ou de mariage, ou en inventent, et envoient un numéro pour les cotisations. Le compte piraté d'un ami peut aussi envoyer le même message à tous ses contacts.",
     "Abatekamutwe bigana komite nyazo z'ubukwe n'amakiriyo cyangwa bakazihimba, bakohereza nimero y'imisanzu. Konti y'inshuti yibwe ishobora kohereza ubutumwa bumwe ku bo izi bose.",
     "Matapeli hunakili kamati halisi za harusi na msiba, au kuunda, na kutuma namba ya michango. Akaunti ya rafiki iliyodukuliwa pia inaweza kutuma ujumbe huo huo kwa kila anayemjua."),
    ("Call the family or committee chair on a number you already know to confirm the event and the contribution number. | Check the name shown when you enter the number in your MoMo app. | If it came from a friend's account, ask the friend by phone whether they really sent it.",
     "Appelez la famille ou le président du comité sur un numéro connu pour confirmer l'événement et le numéro de cotisation. | Vérifiez le nom affiché quand vous saisissez le numéro dans MoMo. | Si le message vient d'un ami, demandez-lui par téléphone s'il l'a vraiment envoyé.",
     "Hamagara umuryango cyangwa umuyobozi wa komite kuri nimero uzi wemeze ibirori n'inimero y'umusanzu. | Reba izina rigaragara iyo wandika nimero muri MoMo. | Niba byaturutse ku nshuti, uyibaze kuri telefone niba yabyohereje koko.",
     "Piga familia au mwenyekiti wa kamati kwa namba unayoijua kuthibitisha tukio na namba ya mchango. | Angalia jina linaloonekana ukiandika namba kwenye MoMo. | Ikiwa kimetoka kwa rafiki, mpigie ahakikishe kama alituma kweli."))

# 24 -------------------------------------------------------------------------------------------------------------- "verify you are human" paste a command
add("paste_command_captcha", "high", ["r:(?:\\b(?:win(?:dows)?\\s?\\+\\s?r|press (?:ctrl|win)|ctrl\\s?\\+\\s?v|paste (?:this|the|it)|powershell|cmd\\.exe|terminal|run (?:this|the) command|copy (?:and|&) paste|collez|kopi|ikope|bandika)\\b)", "r:\\b(?:captcha|verify (?:you are|you're) (?:human|not a robot)|i am not a robot|human verification|fix (?:the )?(?:error|issue)|verification|security check|verifier|emeza|thibitisha|hakiki)\\w*"],
    ("'Verify you are human / fix the error: paste this command' (ClickFix malware trick)", "« Prouvez que vous êtes humain / réparez l'erreur : collez cette commande » (astuce ClickFix)", "«Emeza ko uri umuntu / kosora ikosa: bandika iyi komande» (uburiganya bwa ClickFix)", "«Thibitisha wewe ni binadamu / rekebisha hitilafu: bandika amri hii» (hila ya ClickFix)"),
    ("A web page or message asks you to press Win+R (or open Terminal) and paste a command to 'verify' or 'fix' something. That command installs malware that steals passwords and crypto. No real CAPTCHA ever asks this.",
     "Une page ou un message vous demande d'appuyer sur Win+R (ou d'ouvrir le Terminal) et de coller une commande pour « vérifier » ou « réparer ». Cette commande installe un malware qui vole mots de passe et crypto. Aucun vrai CAPTCHA ne demande cela.",
     "Urupapuro cyangwa ubutumwa bugusaba gukanda Win+R (cyangwa gufungura Terminal) ugashyiramo komande «yo kwemeza» cyangwa «gukosora». Iyo komande ishyiraho malware yiba amagambo y'ibanga na crypto. Nta CAPTCHA nyayo isaba ibyo.",
     "Ukurasa au ujumbe hukuomba ubonyeze Win+R (au ufungue Terminal) na ubandike amri ya «kuthibitisha» au «kurekebisha». Amri hiyo husakinisha programu hasidi inayoiba nywila na crypto. CAPTCHA halisi haiombi hivyo."),
    ("Close the page and do not paste or run anything. | If you already ran it, disconnect from the Internet, run a full antivirus scan, change your passwords from a clean device and move crypto to a new wallet. | Report the site.",
     "Fermez la page et ne collez ni n'exécutez rien. | Si vous l'avez exécutée, déconnectez-vous d'Internet, lancez un antivirus complet, changez vos mots de passe depuis un appareil sain et déplacez vos crypto vers un nouveau portefeuille. | Signalez le site.",
     "Funga urupapuro, ntubandike cyangwa ngo ukore ikintu. | Niba wayikoze, ve kuri Internet, kora scan yuzuye ya antivirus, uhindure amagambo y'ibanga uri ku gikoresho cyizewe uhindure wallet ya crypto. | Menyesha urubuga.",
     "Funga ukurasa na usibandike wala kuendesha chochote. | Ikiwa umeshaendesha, ondoa intaneti, fanya skani kamili ya antivirus, badilisha nywila ukiwa kwenye kifaa safi na uhamishe crypto kwenye pochi mpya. | Ripoti tovuti."), strong=True)

# 25 -------------------------------------------------------------------------------------------------------------- free Wi-Fi login with details
add("free_wifi_login", "medium", ["r:\\b(?:free wi-?fi|wi-?fi (?:gratuit|ya bure|ku buntu)|wifi bure|wifi ku buntu|hotspot)\\b", "r:\\b(?:login|log in|connect|sign in|register|enter|saisissez|connectez|injira|ingia|andika|ingiza)\\w*", "r:\\b(?:phone number|number|card|pin|password|id|numero|carte|mot de passe|nimero|ikarita|namba|kadi|nenosiri)\\b"],
    ("Free Wi-Fi that asks for your number, card or password", "Wi-Fi gratuit qui demande votre numéro, carte ou mot de passe", "Wi-Fi y'ubuntu isaba nimero, ikarita cyangwa ijambo ry'ibanga", "Wi-Fi bure inayoomba namba, kadi au nywila"),
    ("Fake hotspots (an evil twin of a real café or airport name) collect details or watch what you do. A free Wi-Fi never needs your card or mobile-money PIN.",
     "De faux points d'accès (jumeau d'un vrai café ou aéroport) collectent vos données ou observent vos actions. Un Wi-Fi gratuit n'exige jamais votre carte ni votre PIN mobile money.",
     "Hotspot z'impimbano (zisa n'iz'ikawa cyangwa ikibuga cy'indege) zikusanya amakuru cyangwa zikareba ibyo ukora. Wi-Fi y'ubuntu ntisaba ikarita cyangwa PIN ya mobile money.",
     "Hotspot bandia (pacha wa mkahawa au uwanja wa ndege halisi) hukusanya taarifa au kutazama unachofanya. Wi-Fi bure haihitaji kadi wala PIN ya pesa za simu."),
    ("Ask the staff for the exact network name and password. | Never enter card, PIN or banking login on a hotspot page; use mobile data for banking. | Use a VPN and only HTTPS sites; turn off auto-connect.",
     "Demandez au personnel le nom exact du réseau et le mot de passe. | Ne saisissez jamais carte, PIN ou identifiants bancaires sur une page de hotspot ; utilisez les données mobiles pour la banque. | Utilisez un VPN et seulement des sites HTTPS ; désactivez la connexion automatique.",
     "Baza abakozi izina nyaryo ry'umuyoboro n'ijambo ry'ibanga. | Ntuzigere ushyira ikarita, PIN cyangwa konti ya banki ku rupapuro rwa hotspot; koresha data ya telefoni ku bya banki. | Koresha VPN n'imbuga za HTTPS gusa; zimya guhuza byikora.",
     "Waulize wafanyakazi jina halisi la mtandao na nywila. | Kamwe usiweke kadi, PIN au akaunti ya benki kwenye ukurasa wa hotspot; tumia data ya simu kwa benki. | Tumia VPN na tovuti za HTTPS tu; zima kuunganisha kiotomatiki."))

# 26 -------------------------------------------------------------------------------------------------------------- equipment purchase then cheque refund (job)
add("job_equipment_refund", "high", ["JOB", "r:\\b(?:buy|purchase|equipment|laptop|phone|software|supplies|acheter|ordinateur|materiel|kugura|ibikoresho|kununua|vifaa)\\w*", "r:\\b(?:refund|reimburse|cheque|check|rembours|kugaruza|kuzagaruza|nitakurudishia|kurejeshewa|tutakurejeshea|tutagaruza)\\w*"],
    ("Job that makes you buy equipment first and promises a refund or cheque", "Emploi qui vous fait acheter du matériel d'abord avec promesse de remboursement ou chèque", "Akazi kagusaba kugura ibikoresho mbere bakakwizeza kukugaruza cyangwa sheki", "Ajira inayokutaka ununue vifaa kwanza na kuahidi kurejesha au hundi"),
    ("The 'employer' sends a fake cheque or promises a refund, you buy equipment or send the 'balance' to a vendor, and later the cheque bounces. You lose the money.",
     "Le « employeur » envoie un faux chèque ou promet un remboursement, vous achetez le matériel ou envoyez le « solde » à un fournisseur, puis le chèque est rejeté. Vous perdez l'argent.",
     "«Umukoresha» yohereza sheki y'impimbano cyangwa akizeza kugaruza, ugura ibikoresho cyangwa wohereza «ibisigaye» ku mugurisha, nyuma sheki ikanga. Utakaza amafaranga.",
     "«Mwajiri» hutuma hundi bandia au kuahidi kurejesha, wewe unanunua vifaa au kutuma «salio» kwa muuzaji, kisha hundi inakataliwa. Unapoteza pesa."),
    ("Never buy equipment or send money before a verified employer pays you. | A cheque is not cash until your bank confirms it has cleared. | Check the company, the interviewer and the address independently; real employers meet or call you and issue a contract.",
     "N'achetez pas de matériel et n'envoyez pas d'argent avant qu'un employeur vérifié ne vous paie. | Un chèque n'est pas de l'argent tant que la banque ne confirme pas l'encaissement. | Vérifiez l'entreprise, l'interlocuteur et l'adresse indépendamment ; les vrais employeurs vous rencontrent ou appellent et donnent un contrat.",
     "Ntugure ibikoresho cyangwa ngo wohereze amafaranga mbere y'uko umukoresha wemejwe akwishyura. | Sheki si amafaranga kugeza banki ibyemeje. | Genzura ikigo, uwakubajije n'aderesi ubwawe; abakoresha nyabo barahura cyangwa bakaguhamagara bakaguha amasezerano.",
     "Usinunue vifaa wala kutuma pesa kabla mwajiri aliyethibitishwa kukulipa. | Hundi si pesa hadi benki ithibitishe imepita. | Hakiki kampuni, mhoji na anwani kivyako; waajiri halisi hukutana au kukupigia na kutoa mkataba."), strong=True)

# 27 -------------------------------------------------------------------------------------------------------------- withdrawal fee
add("withdrawal_fee_trap", "high", ["r:\\b(?:withdraw\\w*|retrait\\w*|cash ?out|kubikuza|kubikura|kutoa pesa|kutoa faida|kutoa)\\b", "r:\\b(?:fee|fees|tax|taxes|charge|frais|taxe|ada|kodi|umusoro|amafaranga y\\w+|unlock|verification fee|upgrade)\\w*", "r:\\b(?:profit|profits|balance|wallet|account|earnings|gains|inyungu|konti|faida|salio|akaunti)\\b"],
    ("'Pay a fee/tax to withdraw your profits' trap", "Piège « payez des frais/taxes pour retirer vos gains »", "Umutego wa «ishyura amafaranga/umusoro ubikuze inyungu»", "Mtego wa «lipa ada/kodi kutoa faida yako»"),
    ("A fake trading or betting platform shows big 'profits', then says you must pay a tax or fee to withdraw. Paying leads to more fees; the money is not real.",
     "Une fausse plateforme de trading ou de paris affiche de gros « profits » puis exige une taxe ou des frais pour retirer. Payer entraîne d'autres frais ; l'argent n'est pas réel.",
     "Urubuga rw'impimbano rwa trading cyangwa kubeti rwerekana «inyungu» nyinshi, hanyuma rukavuga ko ugomba kwishyura umusoro cyangwa amafaranga kugira ngo ubikuze. Kwishyura bizana andi; amafaranga ntabaho.",
     "Jukwaa bandia la biashara au kubeti huonyesha «faida» kubwa, kisha husema ulipe kodi au ada kutoa. Kulipa huleta ada zaidi; pesa si halisi."),
    ("Stop paying: no legitimate platform deducts the fee outside your balance. | Try to withdraw a small amount first; if it is blocked, treat the whole platform as fake. | Keep screenshots and transaction proofs and report to the police and your operator/bank. | Beware of 'recovery' agents contacting you afterwards.",
     "Arrêtez de payer : aucune plateforme légitime ne prélève des frais hors de votre solde. | Essayez d'abord de retirer une petite somme ; si c'est bloqué, considérez toute la plateforme comme fausse. | Gardez captures et preuves de transactions et signalez à la police et à votre opérateur/banque. | Méfiez-vous des « agents de récupération » qui vous contactent ensuite.",
     "Hagarika kwishyura: nta rubuga rwemewe rukata amafaranga hanze ya konti yawe. | Banza ugerageze gukuramo amafaranga make; niba bibujijwe, ufate urubuga rwose nk'urw'impimbano. | Bika amashusho n'ibimenyetso by'ibikorwa ubimenyeshe polisi na sosiyete/banki. | Wirinde «abafasha kugarura» bakuvugisha nyuma.",
     "Acha kulipa: hakuna jukwaa halali linalokata ada nje ya salio lako. | Jaribu kwanza kutoa kiasi kidogo; kikizuiwa, chukulia jukwaa lote kuwa bandia. | Hifadhi picha na ushahidi wa miamala na uripoti polisi na kampuni ya simu/benki. | Jihadhari na «mawakala wa kurejesha» watakaokutafuta baadaye."), strong=True)

